function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); changeLookupReadonly(f, 'ma_dvcs');
	f._looking = f.getItem('so_ct')._controlBehavior;
	f._looking.add_loading(on$Form$Filter$Before$Loading);
	f._looking2 = f.getItem('so_lsx')._controlBehavior;
	f._looking2.add_loading(on$Form$Filter$Before$Loading);


	changeLookupReadonly(f, 'so_ct');
	changeLookupReadonly(f, 'so_lsx');
}
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}

function on$Form$Filter$Before$Loading(sender, e) {
			var f = sender._element.parentForm;			 
			var g = f.grid, w = g.get_element().parentForm;		
			var kh = f.getItemValue('ma_kh');
			a = [					 
				{Name: 'ma_kh', Type: 'String', Value: kh },
				{Name: 'ma_dvcs', Type: 'String', Value: ''}
			];
			sender.set_memvars(a); 
		}
function onChange$zrpt_bckhsxvt$Filter$ma_kh(o){
	var f = o.parentForm;
	f.setItemValues('so_ct, so_lsx', ['','']);
}

function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, d1 = f.getItem('ngay_ct1').value, d2 = f.getItem('ngay_ct2').value, d3 = f.getItem('ngay_tk').value, d4 = f.getItem('ten_px%l').value;
			g._alterTitle = [null, [['%d1', d1, true],['%d2', d2, true],['%d3', d3, true],['%d4', d4, true]]];
			break;
		default:
			break;
	}
}
